    v_lifecycle_evidence_sha256 := v_attempt.terminal_receipt_sha256;
    v_booking_reference := v_order.confirmation_code;
    v_provider_order_receipt_sha256 := v_attempt.terminal_receipt_sha256;
    v_booking_reference_receipt_sha256 := encode(extensions.digest(convert_to(
      jsonb_build_object(
        'domain', 'iratepilot.flight.notification.booking-reference.v1',
        'order_id', v_order.id::text,
        'event_receipt_id', v_attempt.id::text,
        'confirmation_code', v_order.confirmation_code
      )::text, 'UTF8'
    ), 'sha256'), 'hex');

  elsif p_event_type = 'order_pending' then
    select * into v_case
      from public.flight_reconciliation_cases as reconciliation
     where reconciliation.order_id = v_order.id
       and reconciliation.execution_mode = 'test'
       and reconciliation.execution_scope_sha256 = v_order.execution_scope_sha256
       and reconciliation.subject_type = 'flight_order'
       and reconciliation.subject_id = v_order.id
       and reconciliation.status in ('open', 'investigating', 'blocked')
     order by reconciliation.created_at desc, reconciliation.id desc
     limit 1
     for share;
    if v_order.status <> 'requires_review' or v_case.id is null then
      raise exception 'Flight pending notification requires active review evidence';
    end if;
    v_event_receipt_id := v_case.id::text;
    v_lifecycle_evidence_sha256 := encode(extensions.digest(convert_to(
      jsonb_build_object(
        'domain', 'iratepilot.flight.notification.order-pending.v1',
        'order_id', v_order.id::text,
        'order_status', v_order.status,
        'case_id', v_case.id::text,
        'case_type', v_case.case_type,
        'case_status', v_case.status,
        'expected_state_sha256', v_case.expected_state_sha256,
        'observed_state_sha256', v_case.observed_state_sha256
      )::text, 'UTF8'
    ), 'sha256'), 'hex');

  elsif p_event_type = 'order_failed' then
    select * into v_payment
      from public.flight_payments as payment
     where payment.order_id = v_order.id
       and payment.execution_mode = 'test'
       and payment.execution_scope_sha256 = v_order.execution_scope_sha256
     order by payment.created_at desc, payment.id desc
     limit 1
     for share;
    select * into v_case
      from public.flight_reconciliation_cases as reconciliation
     where reconciliation.order_id = v_order.id
       and reconciliation.execution_mode = 'test'
       and reconciliation.execution_scope_sha256 = v_order.execution_scope_sha256
       and reconciliation.subject_type = 'flight_order'
       and reconciliation.subject_id = v_order.id
       and reconciliation.status = 'resolved'
       and reconciliation.resolution_evidence_sha256 is not null
     order by reconciliation.resolved_at desc, reconciliation.id desc
     limit 1
     for share;
    select * into v_refund_attempt
      from public.flight_payment_operation_attempts as attempt
     where v_payment.id is not null
       and attempt.order_id = v_order.id
       and attempt.payment_id = v_payment.id
       and attempt.operation = 'refund'
       and attempt.state = 'succeeded'
       and attempt.revision = 2
       and attempt.terminal_receipt_sha256 is not null
     order by attempt.prepared_at desc, attempt.id desc
     limit 1
     for share;
    if v_order.status <> 'failed'
      or exists (
        select 1 from public.flight_ticket_documents as document
         where document.order_id = v_order.id
           and document.status not in ('voided', 'refunded', 'failed')
      )
      or (
        v_payment.id is not null
        and (
          v_payment.captured_cents <> v_payment.refunded_cents
          or v_payment.status not in ('failed', 'cancelled', 'refunded')
        )
      ) then
      raise exception 'Flight failed notification requires zero liability';
    end if;
    v_event_receipt_id := coalesce(
      v_refund_attempt.id::text,
      v_case.id::text,
      v_order.id::text
    );
    v_lifecycle_evidence_sha256 := encode(extensions.digest(convert_to(
      jsonb_build_object(
        'domain', 'iratepilot.flight.notification.order-failed.v1',
        'order_id', v_order.id::text,
        'order_status', v_order.status,
        'order_updated_at', v_order.updated_at,
        'payment_id', v_payment.id::text,
        'payment_status', v_payment.status,
        'captured_cents', v_payment.captured_cents,
        'refunded_cents', v_payment.refunded_cents,
        'resolution_evidence_sha256', v_case.resolution_evidence_sha256,
        'refund_terminal_receipt_sha256', v_refund_attempt.terminal_receipt_sha256
      )::text, 'UTF8'
    ), 'sha256'), 'hex');

  else
    select * into v_payment
      from public.flight_payments as payment
     where payment.order_id = v_order.id
       and payment.execution_mode = 'test'
       and payment.execution_scope_sha256 = v_order.execution_scope_sha256
       and payment.processor_code = 'stripe'
       and payment.status = 'refunded'
     order by payment.created_at desc, payment.id desc
     limit 1
     for share;
    select * into v_refund_attempt
      from public.flight_payment_operation_attempts as attempt
     where v_payment.id is not null
       and attempt.order_id = v_order.id
       and attempt.payment_id = v_payment.id
       and attempt.operation = 'refund'
       and attempt.processor_code = 'stripe'
       and attempt.execution_mode = 'test'
       and attempt.execution_scope_sha256 = v_order.execution_scope_sha256
       and attempt.state = 'succeeded'
       and attempt.revision = 2
       and attempt.terminal_receipt_sha256 is not null
     order by attempt.prepared_at desc, attempt.id desc
     limit 1
     for share;
    select * into v_refund_evidence
      from public.flight_payment_refund_evidence as evidence
     where v_refund_attempt.id is not null
       and evidence.attempt_id = v_refund_attempt.id
       and evidence.order_id = v_order.id
       and evidence.payment_id = v_payment.id
       and evidence.execution_mode = 'test'
       and evidence.execution_scope_sha256 = v_order.execution_scope_sha256
       and evidence.terminal_receipt_sha256 = v_refund_attempt.terminal_receipt_sha256
     for share;
    select * into v_case
      from public.flight_reconciliation_cases as reconciliation
     where reconciliation.order_id = v_order.id
       and reconciliation.execution_mode = 'test'
       and reconciliation.execution_scope_sha256 = v_order.execution_scope_sha256
       and reconciliation.status = 'resolved'
       and reconciliation.resolution_evidence_sha256 is not null
       and reconciliation.resolution_code in (
         'payment_reversed', 'duplicate_suppressed'
       )
       and (
         (
           reconciliation.case_type = 'ambiguous_order'
           and reconciliation.subject_type = 'flight_order'
           and reconciliation.subject_id = v_order.id
         )
         or (
           reconciliation.case_type in ('payment_order_mismatch', 'refund_mismatch')
           and reconciliation.subject_type = 'flight_payment'
           and reconciliation.subject_id = v_payment.id
         )
       )
     order by reconciliation.resolved_at desc, reconciliation.id desc
     limit 1
     for share;
    if v_order.status not in ('failed', 'refunded')
      or v_order.provider_order_ref_sha256 is not null
      or v_payment.id is null
      or v_payment.currency <> v_order.currency
      or v_payment.authorized_cents <> v_order.total_cents
      or v_payment.captured_cents <> v_order.total_cents
      or v_payment.refunded_cents <> v_order.total_cents
      or v_refund_attempt.id is null
      or v_refund_evidence.id is null
      or v_refund_evidence.refunded_cents <> v_order.total_cents
      or v_case.id is null
      or exists (
        select 1 from public.flight_ticket_documents as document
         where document.order_id = v_order.id
           and document.status not in ('voided', 'refunded', 'failed')
      ) then
      raise exception 'Flight refund notification requires reconciled refund evidence';
    end if;
    v_event_receipt_id := v_refund_attempt.id::text;
    v_lifecycle_evidence_sha256 := v_refund_evidence.terminal_receipt_sha256;
    v_payment_id := v_payment.id::text;
    v_currency := v_payment.currency;
    v_refunded_amount_minor := v_payment.refunded_cents;
    v_payment_receipt_sha256 := v_refund_attempt.payment_binding_receipt_sha256;
    v_reconciliation_receipt_sha256 := v_case.resolution_evidence_sha256;
  end if;

  if v_event_receipt_id is null
    or v_event_receipt_id !~ '^[0-9a-f-]{36}$'
    or v_lifecycle_evidence_sha256 is null
    or v_lifecycle_evidence_sha256 !~ '^[0-9a-f]{64}$' then
    raise exception 'Flight notification lifecycle evidence is invalid';
  end if;

  v_trusted_receipt_sha256 := encode(extensions.digest(convert_to(
    jsonb_build_object(
      'domain', 'iratepilot.flight.notification.projection.v1',
      'customer_id', v_order.customer_id::text,
      'order_id', v_order.id::text,
      'event_type', p_event_type,
      'event_receipt_id', v_event_receipt_id,
      'lifecycle_evidence_sha256', v_lifecycle_evidence_sha256,
      'origin_iata', v_search.origin_iata,
      'destination_iata', v_search.destination_iata,
      'booking_reference', v_booking_reference,
      'provider_order_receipt_sha256', v_provider_order_receipt_sha256,
      'booking_reference_receipt_sha256', v_booking_reference_receipt_sha256,
      'electronic_ticket_document_receipt_sha256s',
        to_jsonb(v_document_receipts),
      'payment_id', v_payment_id,
      'currency', v_currency,
      'refunded_amount_minor', v_refunded_amount_minor,
      'payment_receipt_sha256', v_payment_receipt_sha256,
      'reconciliation_receipt_sha256', v_reconciliation_receipt_sha256
    )::text, 'UTF8'
  ), 'sha256'), 'hex');

  return query select
    v_order.customer_id,
    v_order.id,
    p_event_type,
    v_event_receipt_id,
    v_order.execution_scope_sha256,
    v_lifecycle_evidence_sha256,
    v_search.origin_iata,
    v_search.destination_iata,
    v_booking_reference,
    v_provider_order_receipt_sha256,
    v_booking_reference_receipt_sha256,
    v_document_receipts,
    v_payment_id,
    v_currency,
    v_refunded_amount_minor,
    v_payment_receipt_sha256,
    v_reconciliation_receipt_sha256,
    v_trusted_receipt_sha256;
end;
$flight_consumer_notification_projection$;

-- Verify the exact sanitized projection again and atomically bridge it to the
-- existing outbox. The recipient is selected from auth.users using the order's
-- durable customer_id; no caller can supply or redirect an email address.
create function public.queue_flight_consumer_notification_v1(
  p_customer_id uuid,
  p_order_id uuid,
  p_event_type text,
  p_event_receipt_id uuid,
  p_lifecycle_evidence_sha256 text,
  p_trusted_evidence_receipt_sha256 text,
  p_template_name text,
  p_dedupe_key text,
  p_subject text,
  p_message text,
  p_action_url text
)
returns table (decision text, email_outbox_id uuid)
language plpgsql
security definer
set search_path = pg_catalog, public, auth
as $queue_flight_consumer_notification$
declare
  v_projection record;
  v_existing public.flight_consumer_notification_outbox_receipts;
  v_outbox public.email_outbox;
  v_recipient_email text;
  v_expected_subject text;
  v_expected_message text;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'Flight notification queue is service-role only';
  end if;

  select * into v_projection
    from public.get_flight_consumer_notification_projection_v1(
      p_customer_id, p_order_id, p_event_type
    );
  if v_projection.order_id is null
    or v_projection.event_receipt_id is distinct from p_event_receipt_id::text
    or v_projection.lifecycle_evidence_sha256
      is distinct from p_lifecycle_evidence_sha256
    or v_projection.trusted_evidence_receipt_sha256
      is distinct from p_trusted_evidence_receipt_sha256 then
    raise exception 'Flight notification evidence changed before queueing';
  end if;

  v_expected_subject := case p_event_type
    when 'order_pending' then 'Your flight order is still processing'
    when 'ticketed' then 'Your flight is booked and ticketed'
    when 'order_failed' then 'Your flight order could not be completed'
    when 'refund_completed' then 'Your flight refund is complete'
  end;
  v_expected_message := case p_event_type
    when 'order_pending' then format(
      'Your %s to %s request is processing. It is not confirmed or ticketed yet. Do not submit another order.',
      v_projection.origin_iata, v_projection.destination_iata
    )
    when 'ticketed' then format(
      'Your %s to %s order has a provider booking reference and electronic-ticket documentation. Review the operating carrier, itinerary, fare conditions, and support details.',
      v_projection.origin_iata, v_projection.destination_iata
    )
    when 'order_failed' then format(
      'Your %s to %s order was not completed. Any payment state must be reconciled before trying again.',
      v_projection.origin_iata, v_projection.destination_iata
    )
    when 'refund_completed' then format(
      'The approved traveler refund for your cancelled %s to %s order was completed and reconciled.',
      v_projection.origin_iata, v_projection.destination_iata
    )
  end;
  if p_template_name is distinct from 'flight_' || p_event_type
    or p_dedupe_key is distinct from format(
      'flight:%s:%s:%s', p_order_id::text, p_event_type, p_event_receipt_id::text
    )
    or p_subject is distinct from v_expected_subject
    or p_message is distinct from v_expected_message
    or p_action_url !~ '^https://[A-Za-z0-9.-]+(:[0-9]{1,5})?/account/flights$' then
    raise exception 'Flight notification content is not the approved projection';
  end if;

  select lower(trim(users.email::text)) into v_recipient_email
    from auth.users as users
   where users.id = v_projection.customer_id
     and users.deleted_at is null
     and users.email_confirmed_at is not null;
  if v_recipient_email is null
    or length(v_recipient_email) > 320
    or v_recipient_email !~ '^[^[:space:]@]+@[^[:space:]@]+$' then
    raise exception 'Flight notification owner email is unavailable';
  end if;

  -- Serialize only this exact business notification; unrelated bookings and
  -- outbox jobs remain concurrent.
  perform pg_advisory_xact_lock(pg_catalog.hashtextextended(p_dedupe_key, 0));
  select * into v_existing
    from public.flight_consumer_notification_outbox_receipts as receipt
   where receipt.order_id = p_order_id
     and receipt.event_type = p_event_type
     and receipt.event_receipt_id = p_event_receipt_id;
  if v_existing.id is not null then
    if v_existing.customer_id is distinct from p_customer_id
      or v_existing.lifecycle_evidence_sha256
        is distinct from p_lifecycle_evidence_sha256
      or v_existing.trusted_evidence_receipt_sha256
        is distinct from p_trusted_evidence_receipt_sha256 then
      raise exception 'Flight notification replay collides';
    end if;
    return query select 'replay'::text, v_existing.email_outbox_id;
    return;
  end if;

  insert into public.email_outbox (
    recipient_email, subject, template_name, template_data,
    status, scheduled_at
  ) values (
    v_recipient_email,
    p_subject,
    p_template_name,
    jsonb_build_object(
      'dedupe_key', p_dedupe_key,
      'message', p_message,
      'action_url', p_action_url
    ),
    'pending',
    clock_timestamp()
  ) returning * into v_outbox;

  insert into public.flight_consumer_notification_outbox_receipts (
    customer_id, order_id, event_type, event_receipt_id,
    lifecycle_evidence_sha256, trusted_evidence_receipt_sha256,
    email_outbox_id, execution_mode, execution_scope_sha256
  ) values (
    p_customer_id, p_order_id, p_event_type, p_event_receipt_id,
    p_lifecycle_evidence_sha256, p_trusted_evidence_receipt_sha256,
    v_outbox.id, 'test', v_projection.execution_scope_sha256
  );
  return query select 'queued'::text, v_outbox.id;
end;
$queue_flight_consumer_notification$;

revoke all on function public.get_flight_consumer_notification_projection_v1(
  uuid, uuid, text
) from public, anon, authenticated, service_role;
revoke all on function public.queue_flight_consumer_notification_v1(
  uuid, uuid, text, uuid, text, text, text, text, text, text, text
) from public, anon, authenticated, service_role;
grant execute on function public.get_flight_consumer_notification_projection_v1(
  uuid, uuid, text
) to service_role;
grant execute on function public.queue_flight_consumer_notification_v1(
  uuid, uuid, text, uuid, text, text, text, text, text, text, text
) to service_role;

commit;

-- Mirrored from migrations/202608250079_flight_consumer_preview_support_intake.sql.
begin;

-- Consumer Preview support intake records owner intent for local staff review.
-- It never enables provider servicing, changes an order, or dispatches network
-- traffic. Migrations 076-078 must already be applied in sequence.
do $flight_consumer_preview_support_079_dependencies$
begin
  if to_regclass('public.flight_service_requests') is null
    or to_regclass('public.flight_consumer_notification_outbox_receipts') is null
    or to_regprocedure(
      'public.assert_flight_consumer_preview_runtime_v1(text,text)'
    ) is null
    or to_regprocedure(
      'public.flight_consumer_preview_control_is_bound_v1(text)'
    ) is null
    or to_regprocedure(
      'public.finalize_flight_consumer_async_duffel_order_v1(uuid,uuid,uuid,text,text,text,timestamptz,timestamptz,jsonb,jsonb)'
    ) is null then
    raise exception 'Flight Consumer Preview support intake requires migrations 068 through 078';
  end if;
  if to_regprocedure('extensions.digest(bytea,text)') is null then
    raise exception 'Flight Consumer Preview support intake requires reviewed SHA-256 support';
  end if;
end;
$flight_consumer_preview_support_079_dependencies$;

-- Preserve the original servicing guard for every insert/update except the
-- transaction-local, authenticated-owner Preview intake created by the RPC
-- below. The special branch requires the exact active test scope while the
-- provider servicing capability remains false.
create function public.enforce_flight_consumer_preview_service_intake_v1()
returns trigger
language plpgsql
security definer
set search_path = pg_catalog, public
as $enforce_flight_consumer_preview_service_intake$
begin
  if tg_op = 'INSERT'
    and new.execution_mode = 'test'
    and new.status = 'requested'
    and coalesce(auth.role(), '') = 'authenticated'
    and auth.uid() is not null
    and new.requested_by = auth.uid()
    and current_setting(
      'app.flight_consumer_preview_support_intake_v1', true
    ) = 'authorized' then
    perform public.assert_flight_consumer_preview_runtime_v1(
      new.execution_scope_sha256, 'ticketing'
    );
    return new;
  end if;

  if not public.flight_runtime_capability_enabled(
    new.execution_mode,
    'servicing',
    null,
    null,
    new.execution_scope_sha256
  ) then
    raise exception 'Flight servicing capability is disabled for % execution',
      new.execution_mode;
  end if;
  return new;
end;
$enforce_flight_consumer_preview_service_intake$;

drop trigger flight_service_requests_runtime_guard
  on public.flight_service_requests;
create trigger flight_service_requests_runtime_guard
before insert or update on public.flight_service_requests
for each row execute function
  public.enforce_flight_consumer_preview_service_intake_v1();

create function public.create_flight_consumer_preview_service_request_v1(
  p_order_id uuid,
  p_request_type text,
  p_reason_code text,
  p_idempotency_key_sha256 text
)
returns table (
  decision text,
  service_request_id uuid,
  order_id uuid,
  request_type text,
  reason_code text,
  request_status text,
  created_at timestamptz,
  updated_at timestamptz
)
language plpgsql
security definer
set search_path = pg_catalog, public, extensions
as $create_flight_consumer_preview_service_request$
declare
  v_actor uuid;
  v_order public.flight_orders;
  v_request public.flight_service_requests;
  v_request_sha256 text;
  v_inserted boolean := false;
begin
  if coalesce(auth.role(), '') <> 'authenticated' or auth.uid() is null then
    raise exception 'Flight Consumer Preview support intake requires authentication'
      using errcode = '42501';
  end if;
  v_actor := auth.uid();
  if p_order_id is null
    or p_request_type not in (
      'cancel', 'change', 'refund', 'schedule_change',
      'name_correction', 'document_reissue'
    )
    or p_reason_code is null
    or p_reason_code !~ '^[a-z][a-z0-9_]{1,63}$'
    or not (
      (p_request_type = 'cancel'
        and p_reason_code in ('plans_changed', 'duplicate_test_booking'))
      or (p_request_type = 'change'
        and p_reason_code in ('travel_date_change', 'route_change'))
      or (p_request_type = 'refund'
        and p_reason_code in ('test_refund_review', 'duplicate_test_booking'))
      or (p_request_type = 'schedule_change'
        and p_reason_code in ('schedule_change_review', 'connection_risk'))
      or (p_request_type = 'name_correction'
        and p_reason_code = 'fictional_name_correction')
      or (p_request_type = 'document_reissue'
        and p_reason_code = 'test_document_review')
    )
    or p_idempotency_key_sha256 is null
    or p_idempotency_key_sha256 !~ '^[0-9a-f]{64}$' then
    raise exception 'Flight Consumer Preview support intake is invalid'
      using errcode = '23514';
  end if;

  select * into v_order
    from public.flight_orders as candidate
   where candidate.id = p_order_id
   for update;
  if not found
    or v_order.customer_id <> v_actor
    or v_order.consumer_flow_version <> 1
    or v_order.execution_mode <> 'test'
    or v_order.provider_code <> 'duffel'
    or v_order.status <> 'ticketed'
    or v_order.provider_order_ref_ciphertext is null
    or v_order.provider_order_ref_sha256 is null then
    raise exception 'Flight Consumer Preview support intake order is ineligible'
      using errcode = '23514';
  end if;
  perform public.assert_flight_consumer_preview_runtime_v1(
    v_order.execution_scope_sha256, 'ticketing'
  );
  if not public.flight_consumer_preview_control_is_bound_v1(
    v_order.execution_scope_sha256
  )
    or not exists (
      select 1 from public.flight_payments as payment
       where payment.order_id = v_order.id
         and payment.execution_mode = 'test'
         and payment.execution_scope_sha256 = v_order.execution_scope_sha256
         and payment.processor_code = 'stripe'
         and payment.currency = v_order.currency
         and payment.authorized_cents = v_order.total_cents
         and payment.captured_cents = v_order.total_cents
         and payment.refunded_cents = 0
         and payment.status = 'captured'
    )
    or not exists (
      select 1 from public.flight_passenger_refs as passenger
       where passenger.order_id = v_order.id
         and passenger.execution_mode = 'test'
         and passenger.execution_scope_sha256 = v_order.execution_scope_sha256
    )
    or exists (
      select 1 from public.flight_passenger_refs as passenger
       where passenger.order_id = v_order.id
         and passenger.execution_mode = 'test'
         and passenger.execution_scope_sha256 = v_order.execution_scope_sha256
         and (
           select count(*)
             from public.flight_ticket_documents as document
            where document.order_id = v_order.id
              and document.passenger_ref_id = passenger.id
              and document.execution_mode = 'test'
              and document.execution_scope_sha256 = v_order.execution_scope_sha256
              and document.document_type = 'electronic_ticket'
              and document.status = 'issued'
         ) <> 1
    ) then
    raise exception 'Flight Consumer Preview support intake lacks finalized ticket evidence'
      using errcode = '23514';
  end if;
  -- The request digest binds only the idempotency identity and owner/order
  -- scope. Reusing a key with a different enum payload is detected below.
  v_request_sha256 := encode(extensions.digest(convert_to(
    'iratepilot.flight.consumer-preview.service-request.v1' || chr(10)
      || jsonb_build_object(
        'customer_id', v_actor::text,
        'order_id', v_order.id::text,
        'execution_scope_sha256', v_order.execution_scope_sha256,
        'idempotency_key_sha256', p_idempotency_key_sha256
      )::text,
    'UTF8'
  ), 'sha256'), 'hex');

  -- Check the idempotency identity before creation so one key can never be
  -- reused to smuggle a different enum-only payload.
  select * into v_request
    from public.flight_service_requests as idempotent_replay
   where idempotent_replay.order_id = v_order.id
     and idempotent_replay.request_sha256 = v_request_sha256
   for update;
  if found then
    if v_request.requested_by <> v_actor
      or v_request.execution_mode <> 'test'
      or v_request.execution_scope_sha256 <> v_order.execution_scope_sha256
      or v_request.request_type <> p_request_type
      or v_request.reason_code <> p_reason_code then
      raise exception 'Flight Consumer Preview support idempotency key collides'
        using errcode = '23505';
    end if;
    return query select
      'replay'::text,
      v_request.id,
      v_request.order_id,
      v_request.request_type,
      v_request.reason_code,
      v_request.status,
      v_request.created_at,
      v_request.updated_at;
    return;
  end if;

  if (
    select count(*)
      from public.flight_service_requests as existing_request
     where existing_request.order_id = v_order.id
       and existing_request.execution_mode = 'test'
       and existing_request.execution_scope_sha256 = v_order.execution_scope_sha256
       and existing_request.status in (
         'requested', 'quoted', 'accepted', 'processing', 'requires_review'
       )
  ) >= 12 then
    raise exception 'Flight Consumer Preview support intake limit reached'
      using errcode = '23514';
  end if;

  perform set_config(
    'app.flight_consumer_preview_support_intake_v1', 'authorized', true
  );
  insert into public.flight_service_requests (
    order_id, requested_by, execution_mode, execution_scope_sha256,
    request_type, reason_code, secure_request_ref, request_sha256, status
  ) values (
    v_order.id, v_actor, 'test', v_order.execution_scope_sha256,
    p_request_type, p_reason_code, null, v_request_sha256, 'requested'
  )
  on conflict on constraint
    flight_service_requests_order_id_request_sha256_key do nothing
  returning * into v_request;
  v_inserted := found;
  if not v_inserted then
    select * into v_request
      from public.flight_service_requests as replay
     where replay.order_id = v_order.id
       and replay.request_sha256 = v_request_sha256
     for update;
  end if;
  if v_request.id is null
    or v_request.order_id <> v_order.id
    or v_request.requested_by <> v_actor
    or v_request.execution_mode <> 'test'
    or v_request.execution_scope_sha256 <> v_order.execution_scope_sha256
    or v_request.request_type <> p_request_type
    or v_request.reason_code <> p_reason_code then
    raise exception 'Flight Consumer Preview support idempotency key collides'
      using errcode = '23505';
  end if;

  return query select
    case when v_inserted then 'created'::text else 'replay'::text end,
    v_request.id,
    v_request.order_id,
    v_request.request_type,
    v_request.reason_code,
    v_request.status,
    v_request.created_at,
    v_request.updated_at;
end;
$create_flight_consumer_preview_service_request$;

create function public.list_flight_consumer_preview_service_requests_v1(
  p_order_id uuid default null
)
returns table (
  service_request_id uuid,
  order_id uuid,
  request_type text,
  reason_code text,
  request_status text,
  created_at timestamptz,
  updated_at timestamptz
)
language plpgsql
volatile
security definer
set search_path = pg_catalog, public
as $list_flight_consumer_preview_service_requests$
declare
  v_actor uuid;
  v_scope text;
begin
  if coalesce(auth.role(), '') <> 'authenticated' or auth.uid() is null then
    raise exception 'Flight Consumer Preview support ledger requires authentication'
      using errcode = '42501';
  end if;
  v_actor := auth.uid();
  select control.bound_execution_scope_sha256 into v_scope
    from public.flight_runtime_controls as control
   where control.control_key = 'global';
  perform public.assert_flight_consumer_preview_runtime_v1(v_scope, 'ticketing');

  return query
  select
    request.id,
    request.order_id,
    request.request_type,
    request.reason_code,
    request.status,
    request.created_at,
    request.updated_at
  from public.flight_service_requests as request
  join public.flight_orders as owned_order on owned_order.id = request.order_id
  where owned_order.customer_id = v_actor
    and owned_order.consumer_flow_version = 1
    and owned_order.execution_mode = 'test'
    and owned_order.execution_scope_sha256 = v_scope
    and owned_order.provider_code = 'duffel'
    and request.requested_by = v_actor
    and request.execution_mode = 'test'
    and request.execution_scope_sha256 = v_scope
    and (p_order_id is null or request.order_id = p_order_id)
  order by request.created_at desc, request.id desc
  limit 200;
end;
$list_flight_consumer_preview_service_requests$;

create function public.list_flight_consumer_admin_service_requests_v1(
  p_limit integer default 50,
  p_status text default null
)
returns table (
  service_request_id uuid,
  order_id uuid,
  customer_id uuid,
  confirmation_code text,
  order_status text,
  request_type text,
  reason_code text,
  request_status text,
  created_at timestamptz,
  updated_at timestamptz
)
language plpgsql
volatile
security definer
set search_path = pg_catalog, public
as $list_flight_consumer_admin_service_requests$
declare
  v_actor uuid;
  v_scope text;
begin
  if coalesce(auth.role(), '') <> 'authenticated' or auth.uid() is null then
    raise exception 'Flight Consumer Preview support administration requires authentication'
      using errcode = '42501';
  end if;
  v_actor := auth.uid();
  if not exists (
    select 1 from public.profiles as profile
     where profile.id = v_actor and profile.role = 'admin'
  ) then
    raise exception 'Flight Consumer Preview support administration requires an administrator'
      using errcode = '42501';
  end if;
  if p_limit is null or p_limit < 1 or p_limit > 100
    or (
      p_status is not null
      and p_status not in (
        'requested', 'quoted', 'accepted', 'processing', 'completed',
        'declined', 'failed', 'requires_review'
      )
    ) then
    raise exception 'Flight Consumer Preview support administration query is invalid'
      using errcode = '23514';
  end if;
  select control.bound_execution_scope_sha256 into v_scope
    from public.flight_runtime_controls as control
   where control.control_key = 'global';
  perform public.assert_flight_consumer_preview_runtime_v1(v_scope, 'ticketing');

  return query
  select
    request.id,
    request.order_id,
    support_order.customer_id,
    support_order.confirmation_code,
    support_order.status,
    request.request_type,
    request.reason_code,
    request.status,
    request.created_at,
    request.updated_at
  from public.flight_service_requests as request
  join public.flight_orders as support_order on support_order.id = request.order_id
  where support_order.consumer_flow_version = 1
    and support_order.execution_mode = 'test'
    and support_order.execution_scope_sha256 = v_scope
    and support_order.provider_code = 'duffel'
    and request.execution_mode = 'test'
    and request.execution_scope_sha256 = v_scope
    and (p_status is null or request.status = p_status)
  order by request.created_at desc, request.id desc
  limit p_limit;
end;
$list_flight_consumer_admin_service_requests$;

revoke all on function
  public.enforce_flight_consumer_preview_service_intake_v1()
from public, anon, authenticated, service_role;
revoke all on function
  public.create_flight_consumer_preview_service_request_v1(uuid,text,text,text),
  public.list_flight_consumer_preview_service_requests_v1(uuid),
  public.list_flight_consumer_admin_service_requests_v1(integer,text)
from public, anon, authenticated, service_role;

grant execute on function
  public.create_flight_consumer_preview_service_request_v1(uuid,text,text,text),
  public.list_flight_consumer_preview_service_requests_v1(uuid),
  public.list_flight_consumer_admin_service_requests_v1(integer,text)
to authenticated;

comment on function public.create_flight_consumer_preview_service_request_v1(uuid,text,text,text)
is 'Owner-authenticated, enum-only Consumer Preview support intake. It never enables or dispatches provider servicing.';
comment on function public.list_flight_consumer_preview_service_requests_v1(uuid)
is 'Owner-scoped Consumer Preview support request visibility without provider or passenger references.';
comment on function public.list_flight_consumer_admin_service_requests_v1(integer,text)
is 'Administrator-only Consumer Preview local support queue; read-only and test-scope bound.';

commit;

