  p_reason text
)
returns boolean
language sql
immutable
parallel safe
set search_path = ''
as $$
  select p_reason is null or p_reason in (
    'template_not_allowlisted',
    'payload_schema_invalid',
    'logical_dedupe_invalid',
    'source_record_missing',
    'source_state_stale',
    'recipient_binding_invalid',
    'recipient_not_allowlisted',
    'recipient_suppressed',
    'action_url_invalid'
  );
$$;

