    or (
      execution_mode <> 'synthetic'
      and provider_order_ref_ciphertext is not null
      and provider_order_ref_ciphertext
        ~ '^enc:v[1-9][0-9]*:[A-Za-z0-9_-]+$'
      and char_length(split_part(provider_order_ref_ciphertext, ':', 3))
