-- Associate only the single captured-payment TEST create-order attempt whose
-- immutable offer digest matches the signed webhook. Dispatching is admitted
-- as a candidate, never as a resolved link.
create function public.enqueue_flight_consumer_duffel_pending_webhook_link_v1(
  p_ledger_id uuid,
  p_expected_ledger_revision integer,
  p_provider_order_ref_sha256 text,
  p_provider_offer_ref_sha256 text
)
returns table (
  pending_link_id uuid,
  pending_revision integer,
  pending_state text
)
language plpgsql
security definer
set search_path = pg_catalog, public, extensions
as $enqueue_flight_consumer_duffel_pending_webhook_link$
#variable_conflict error
declare
  v_ledger public.flight_consumer_webhook_ledger;
  v_pending public.flight_consumer_duffel_webhook_pending_links;
  v_resolution public.flight_consumer_duffel_webhook_pending_link_resolutions;
  v_candidate_count integer;
  v_order_id uuid;
  v_customer_id uuid;
  v_payment_id uuid;
  v_attempt_id uuid;
  v_association_receipt_sha256 text;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'Flight Duffel pending webhook linkage is service-role only';
  end if;
  if p_ledger_id is null
    or p_expected_ledger_revision not between 0 and 2
    or p_provider_order_ref_sha256 is null
    or p_provider_order_ref_sha256 !~ '^[0-9a-f]{64}$'
    or p_provider_offer_ref_sha256 is null
    or p_provider_offer_ref_sha256 !~ '^[0-9a-f]{64}$' then
    raise exception 'Flight Duffel pending webhook association is invalid';
  end if;

  select ledger.* into v_ledger
    from public.flight_consumer_webhook_ledger as ledger
   where ledger.id = p_ledger_id for update;
  if not found
    or v_ledger.revision <> p_expected_ledger_revision
    or v_ledger.source <> 'duffel'
    or v_ledger.event_type <> 'order.created'
    or v_ledger.execution_mode <> 'test'
    or v_ledger.provider_live_mode is distinct from false
    or v_ledger.order_id is not null
    or v_ledger.payment_id is not null
    or v_ledger.provider_attempt_id is not null
    or v_ledger.provider_order_ref_sha256
      is distinct from p_provider_order_ref_sha256
    or v_ledger.provider_offer_ref_sha256
      is distinct from p_provider_offer_ref_sha256 then
    raise exception 'Flight Duffel pending webhook ledger identity is unavailable';
  end if;
  perform public.assert_flight_consumer_preview_runtime_v1(
    v_ledger.execution_scope_sha256, 'provider_event'
  );

  -- Exact replay consults the append-only association before any mutable
  -- order/payment state. A later refund or lifecycle change cannot strand the
  -- signed event after enqueue already certified the captured-payment link.
  select pending.* into v_pending
    from public.flight_consumer_duffel_webhook_pending_links as pending
   where pending.ledger_id = v_ledger.id;
  if found then
    v_association_receipt_sha256 := encode(extensions.digest(convert_to(
      jsonb_build_object(
        'domain', 'iratepilot.flight.duffel-webhook-pending-link.v1',
        'ledger_id', v_ledger.id::text,
        'event_id_sha256', v_ledger.event_id_sha256,
        'semantic_sha256', v_ledger.semantic_sha256,
        'verification_receipt_sha256', v_ledger.verification_receipt_sha256,
        'order_id', v_pending.order_id::text,
        'customer_id', v_pending.customer_id::text,
        'payment_id', v_pending.payment_id::text,
        'provider_attempt_id', v_pending.provider_attempt_id::text,
        'execution_scope_sha256', v_ledger.execution_scope_sha256,
        'provider_offer_ref_sha256', p_provider_offer_ref_sha256,
        'provider_order_ref_sha256', p_provider_order_ref_sha256
      )::text, 'UTF8'), 'sha256'), 'hex');
    if v_pending.execution_mode <> 'test'
      or v_pending.execution_scope_sha256 <> v_ledger.execution_scope_sha256
      or v_pending.provider_offer_ref_sha256 <> p_provider_offer_ref_sha256
      or v_pending.provider_order_ref_sha256 <> p_provider_order_ref_sha256
      or v_pending.association_receipt_sha256
        <> v_association_receipt_sha256 then
      raise exception 'Flight Duffel pending webhook association replay collides';
    end if;
    select resolution.* into v_resolution
      from public.flight_consumer_duffel_webhook_pending_link_resolutions
        as resolution
     where resolution.pending_link_id = v_pending.id;
    return query select v_pending.id,
      case when v_resolution.id is null then 0 else 1 end,
      coalesce(v_resolution.outcome, 'pending'::text);
    return;
  end if;

  select count(*)::integer into v_candidate_count
    from public.flight_orders as flight_order
    join public.flight_offers as offer
      on offer.id = flight_order.offer_id
     and offer.search_id = flight_order.search_id
    join public.flight_provider_request_attempts as attempt
      on attempt.order_id = flight_order.id
     and attempt.customer_id = flight_order.customer_id
     and attempt.offer_id = offer.id
     and attempt.operation = 'create_order'
     and attempt.consumer_flow_version = 1
    join public.flight_payments as payment
      on payment.order_id = flight_order.id
     and payment.processor_code = 'stripe'
     and payment.status = 'captured'
     and payment.authorized_cents = flight_order.total_cents
     and payment.captured_cents = flight_order.total_cents
     and payment.refunded_cents = 0
   where flight_order.consumer_flow_version = 1
     and flight_order.execution_mode = 'test'
     and flight_order.execution_scope_sha256 = v_ledger.execution_scope_sha256
     and flight_order.provider_code = 'duffel'
     and flight_order.status in (
       'order_creating', 'requires_review', 'booked',
       'ticketing_pending', 'ticketed'
     )
     and offer.execution_mode = 'test'
     and offer.execution_scope_sha256 = v_ledger.execution_scope_sha256
     and offer.provider_code = 'duffel'
     and offer.provider_offer_ref_sha256 = p_provider_offer_ref_sha256
     and attempt.execution_mode = 'test'
     and attempt.execution_scope_sha256 = v_ledger.execution_scope_sha256
     and attempt.provider_code = 'duffel'
     and not attempt.retry_authorized
     and (
       (attempt.state = 'dispatching' and attempt.revision = 1)
       or (attempt.state in ('succeeded', 'failed', 'ambiguous')
         and attempt.revision = 2)
     )
     and payment.execution_mode = 'test'
     and payment.execution_scope_sha256 = v_ledger.execution_scope_sha256
     and payment.currency = flight_order.currency;
  if v_candidate_count = 0 then return; end if;
  if v_candidate_count <> 1 then
    raise exception 'Flight Duffel pending webhook association is not unique';
  end if;

  select flight_order.id, flight_order.customer_id, payment.id, attempt.id
    into v_order_id, v_customer_id, v_payment_id, v_attempt_id
    from public.flight_orders as flight_order
    join public.flight_offers as offer
      on offer.id = flight_order.offer_id
     and offer.search_id = flight_order.search_id
    join public.flight_provider_request_attempts as attempt
      on attempt.order_id = flight_order.id
     and attempt.customer_id = flight_order.customer_id
     and attempt.offer_id = offer.id
     and attempt.operation = 'create_order'
     and attempt.consumer_flow_version = 1
    join public.flight_payments as payment
      on payment.order_id = flight_order.id
     and payment.processor_code = 'stripe'
     and payment.status = 'captured'
     and payment.authorized_cents = flight_order.total_cents
     and payment.captured_cents = flight_order.total_cents
     and payment.refunded_cents = 0
   where flight_order.consumer_flow_version = 1
     and flight_order.execution_mode = 'test'
     and flight_order.execution_scope_sha256 = v_ledger.execution_scope_sha256
     and flight_order.provider_code = 'duffel'
     and flight_order.status in (
       'order_creating', 'requires_review', 'booked',
       'ticketing_pending', 'ticketed'
     )
     and offer.execution_mode = 'test'
     and offer.execution_scope_sha256 = v_ledger.execution_scope_sha256
     and offer.provider_code = 'duffel'
     and offer.provider_offer_ref_sha256 = p_provider_offer_ref_sha256
     and attempt.execution_mode = 'test'
     and attempt.execution_scope_sha256 = v_ledger.execution_scope_sha256
     and attempt.provider_code = 'duffel'
     and not attempt.retry_authorized
     and (
       (attempt.state = 'dispatching' and attempt.revision = 1)
       or (attempt.state in ('succeeded', 'failed', 'ambiguous')
         and attempt.revision = 2)
     )
     and payment.execution_mode = 'test'
     and payment.execution_scope_sha256 = v_ledger.execution_scope_sha256
     and payment.currency = flight_order.currency
   for share of flight_order, offer, attempt, payment;

  v_association_receipt_sha256 := encode(extensions.digest(convert_to(
    jsonb_build_object(
      'domain', 'iratepilot.flight.duffel-webhook-pending-link.v1',
      'ledger_id', v_ledger.id::text,
      'event_id_sha256', v_ledger.event_id_sha256,
      'semantic_sha256', v_ledger.semantic_sha256,
      'verification_receipt_sha256', v_ledger.verification_receipt_sha256,
      'order_id', v_order_id::text,
      'customer_id', v_customer_id::text,
      'payment_id', v_payment_id::text,
      'provider_attempt_id', v_attempt_id::text,
      'execution_scope_sha256', v_ledger.execution_scope_sha256,
      'provider_offer_ref_sha256', p_provider_offer_ref_sha256,
      'provider_order_ref_sha256', p_provider_order_ref_sha256
    )::text, 'UTF8'), 'sha256'), 'hex');

  insert into public.flight_consumer_duffel_webhook_pending_links (
    ledger_id, order_id, customer_id, payment_id, provider_attempt_id,
    execution_mode, execution_scope_sha256, provider_offer_ref_sha256,
    provider_order_ref_sha256, association_receipt_sha256
  ) values (
    v_ledger.id, v_order_id, v_customer_id, v_payment_id, v_attempt_id,
    'test', v_ledger.execution_scope_sha256, p_provider_offer_ref_sha256,
    p_provider_order_ref_sha256, v_association_receipt_sha256
  ) on conflict (ledger_id) do nothing;

  select pending.* into v_pending
    from public.flight_consumer_duffel_webhook_pending_links as pending
   where pending.ledger_id = v_ledger.id;
  if not found
    or v_pending.order_id <> v_order_id
    or v_pending.customer_id <> v_customer_id
    or v_pending.payment_id <> v_payment_id
    or v_pending.provider_attempt_id <> v_attempt_id
    or v_pending.execution_mode <> 'test'
    or v_pending.execution_scope_sha256 <> v_ledger.execution_scope_sha256
    or v_pending.provider_offer_ref_sha256 <> p_provider_offer_ref_sha256
    or v_pending.provider_order_ref_sha256 <> p_provider_order_ref_sha256
    or v_pending.association_receipt_sha256
      <> v_association_receipt_sha256 then
    raise exception 'Flight Duffel pending webhook association replay collides';
  end if;
  select resolution.* into v_resolution
    from public.flight_consumer_duffel_webhook_pending_link_resolutions as resolution
   where resolution.pending_link_id = v_pending.id;
  return query select v_pending.id,
    case when v_resolution.id is null then 0 else 1 end,
    coalesce(v_resolution.outcome, 'pending'::text);
end;
$enqueue_flight_consumer_duffel_pending_webhook_link$;

-- Resolve by exact revision only after the associated provider attempt reaches
-- a terminal state. A successful result exposes the immutable local identity;
-- failure/ambiguity or an order-digest conflict records review evidence.
-- Dispatching and a success not yet durably finalized stay pending.
create function public.resolve_flight_consumer_duffel_pending_webhook_link_v1(
  p_pending_link_id uuid,
  p_expected_pending_revision integer
)
returns table (
  pending_link_id uuid,
  pending_revision integer,
  pending_state text,
  order_id uuid,
  customer_id uuid,
  provider_attempt_id uuid,
  order_status text,
  execution_scope_sha256 text
)
language plpgsql
security definer
set search_path = pg_catalog, public, extensions
as $resolve_flight_consumer_duffel_pending_webhook_link$
#variable_conflict error
declare
  v_pending public.flight_consumer_duffel_webhook_pending_links;
  v_resolution public.flight_consumer_duffel_webhook_pending_link_resolutions;
  v_ledger public.flight_consumer_webhook_ledger;
  v_order public.flight_orders;
  v_attempt public.flight_provider_request_attempts;
  v_outcome text;
  v_resolution_receipt_sha256 text;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'Flight Duffel pending webhook resolution is service-role only';
  end if;
  if p_pending_link_id is null
    or p_expected_pending_revision not in (0, 1) then
    raise exception 'Flight Duffel pending webhook resolution CAS is invalid';
  end if;
  select pending.* into v_pending
    from public.flight_consumer_duffel_webhook_pending_links as pending
   where pending.id = p_pending_link_id for share;
  if not found or v_pending.execution_mode <> 'test' then
    raise exception 'Flight Duffel pending webhook association is unavailable';
  end if;
  perform public.assert_flight_consumer_preview_runtime_v1(
    v_pending.execution_scope_sha256, 'provider_event'
  );
  select ledger.* into v_ledger
    from public.flight_consumer_webhook_ledger as ledger
   where ledger.id = v_pending.ledger_id for share;
  select flight_order.* into v_order
    from public.flight_orders as flight_order
   where flight_order.id = v_pending.order_id
     and flight_order.customer_id = v_pending.customer_id for share;
  select attempt.* into v_attempt
    from public.flight_provider_request_attempts as attempt
   where attempt.id = v_pending.provider_attempt_id for share;
  if v_ledger.id is null or v_order.id is null or v_attempt.id is null
    or v_ledger.source <> 'duffel'
    or v_ledger.event_type <> 'order.created'
    or v_ledger.execution_mode <> 'test'
    or v_ledger.execution_scope_sha256 <> v_pending.execution_scope_sha256
    or v_ledger.provider_live_mode is distinct from false
    or v_ledger.order_id is not null
    or v_ledger.payment_id is not null
    or v_ledger.provider_attempt_id is not null
    or v_ledger.provider_offer_ref_sha256
      <> v_pending.provider_offer_ref_sha256
    or v_ledger.provider_order_ref_sha256
      <> v_pending.provider_order_ref_sha256
    or v_order.consumer_flow_version <> 1
    or v_order.execution_mode <> 'test'
    or v_order.execution_scope_sha256 <> v_pending.execution_scope_sha256
    or v_order.provider_code <> 'duffel'
    or v_attempt.order_id <> v_order.id
    or v_attempt.customer_id <> v_order.customer_id
    or v_attempt.offer_id <> v_order.offer_id
    or v_attempt.operation <> 'create_order'
    or v_attempt.consumer_flow_version <> 1
    or v_attempt.execution_mode <> 'test'
    or v_attempt.execution_scope_sha256 <> v_pending.execution_scope_sha256
    or v_attempt.provider_code <> 'duffel'
    or v_attempt.retry_authorized
    or not exists (
      select 1 from public.flight_offers as offer
       where offer.id = v_order.offer_id
         and offer.search_id = v_order.search_id
         and offer.execution_mode = 'test'
         and offer.execution_scope_sha256 = v_pending.execution_scope_sha256
         and offer.provider_code = 'duffel'
         and offer.provider_offer_ref_sha256
           = v_pending.provider_offer_ref_sha256
    )
    or not exists (
      select 1 from public.flight_payments as payment
       where payment.id = v_pending.payment_id
         and payment.order_id = v_order.id
         and payment.execution_mode = 'test'
         and payment.execution_scope_sha256 = v_pending.execution_scope_sha256
         and payment.processor_code = 'stripe'
         and payment.authorized_cents = v_order.total_cents
         and payment.currency = v_order.currency
    ) then
    raise exception 'Flight Duffel pending webhook association changed';
  end if;

  select resolution.* into v_resolution
    from public.flight_consumer_duffel_webhook_pending_link_resolutions as resolution
   where resolution.pending_link_id = v_pending.id;
  if found then
    if p_expected_pending_revision not in (0, 1)
      or v_resolution.ledger_id <> v_pending.ledger_id
      or v_resolution.attempt_terminal_state <> v_attempt.state
      or v_resolution.attempt_terminal_revision <> v_attempt.revision
      or v_resolution.attempt_terminal_receipt_sha256
        <> v_attempt.terminal_receipt_sha256 then
      raise exception 'Flight Duffel pending webhook resolution replay collides';
    end if;
    return query select v_pending.id, 1, v_resolution.outcome,
      case when v_resolution.outcome = 'linked' then v_order.id end,
      case when v_resolution.outcome = 'linked' then v_order.customer_id end,
      case when v_resolution.outcome = 'linked' then v_attempt.id end,
      case when v_resolution.outcome = 'linked' then v_order.status end,
      case when v_resolution.outcome = 'linked'
        then v_pending.execution_scope_sha256 end;
    return;
  end if;
  if p_expected_pending_revision <> 0 then
    raise exception 'Flight Duffel pending webhook resolution CAS failed';
  end if;
  if v_attempt.state = 'dispatching' and v_attempt.revision = 1 then
    return query select v_pending.id, 0, 'pending'::text,
      null::uuid, null::uuid, null::uuid, null::text, null::text;
    return;
  end if;
  if v_attempt.state = 'succeeded' and v_attempt.revision = 2
    and v_order.provider_order_ref_sha256 is null then
    return query select v_pending.id, 0, 'pending'::text,
      null::uuid, null::uuid, null::uuid, null::text, null::text;
    return;
  elsif v_attempt.state = 'succeeded' and v_attempt.revision = 2
    and v_order.provider_order_ref_sha256
      = v_pending.provider_order_ref_sha256 then
    v_outcome := 'linked';
  elsif v_attempt.state = 'succeeded' and v_attempt.revision = 2 then
    v_outcome := 'review';
  elsif v_attempt.state in ('failed', 'ambiguous') and v_attempt.revision = 2 then
    v_outcome := 'review';
  else
    raise exception 'Flight Duffel pending webhook attempt state is invalid';
  end if;
  if v_attempt.terminal_receipt_sha256 is null then
    raise exception 'Flight Duffel pending webhook terminal evidence is incomplete';
  end if;
  v_resolution_receipt_sha256 := encode(extensions.digest(convert_to(
    jsonb_build_object(
      'domain', 'iratepilot.flight.duffel-webhook-pending-resolution.v1',
      'pending_link_id', v_pending.id::text,
      'ledger_id', v_pending.ledger_id::text,
      'association_receipt_sha256', v_pending.association_receipt_sha256,
      'provider_attempt_id', v_attempt.id::text,
      'attempt_terminal_state', v_attempt.state,
      'attempt_terminal_revision', v_attempt.revision,
      'attempt_terminal_receipt_sha256', v_attempt.terminal_receipt_sha256,
      'outcome', v_outcome
    )::text, 'UTF8'), 'sha256'), 'hex');
  insert into public.flight_consumer_duffel_webhook_pending_link_resolutions (
    pending_link_id, ledger_id, outcome, attempt_terminal_state,
    attempt_terminal_revision, attempt_terminal_receipt_sha256,
    resolution_receipt_sha256
  ) values (
    v_pending.id, v_pending.ledger_id, v_outcome, v_attempt.state,
    v_attempt.revision, v_attempt.terminal_receipt_sha256,
    v_resolution_receipt_sha256
  ) on conflict (pending_link_id) do nothing;
  select resolution.* into v_resolution
    from public.flight_consumer_duffel_webhook_pending_link_resolutions as resolution
   where resolution.pending_link_id = v_pending.id;
  if not found
    or v_resolution.ledger_id <> v_pending.ledger_id
    or v_resolution.outcome <> v_outcome
    or v_resolution.attempt_terminal_state <> v_attempt.state
    or v_resolution.attempt_terminal_revision <> v_attempt.revision
    or v_resolution.attempt_terminal_receipt_sha256
      <> v_attempt.terminal_receipt_sha256
    or v_resolution.resolution_receipt_sha256
      <> v_resolution_receipt_sha256 then
    raise exception 'Flight Duffel pending webhook resolution CAS collided';
  end if;
  return query select v_pending.id, 1, v_resolution.outcome,
    case when v_resolution.outcome = 'linked' then v_order.id end,
    case when v_resolution.outcome = 'linked' then v_order.customer_id end,
    case when v_resolution.outcome = 'linked' then v_attempt.id end,
    case when v_resolution.outcome = 'linked' then v_order.status end,
    case when v_resolution.outcome = 'linked'
      then v_pending.execution_scope_sha256 end;
end;
$resolve_flight_consumer_duffel_pending_webhook_link$;

-- Bounded post-terminal convergence only resolves local append-only evidence.
-- It never contacts Duffel and cannot dispatch or retry a provider operation.
create function public.resolve_flight_consumer_duffel_pending_links_for_attempt_v1(
  p_attempt_id uuid,
  p_expected_terminal_revision integer,
  p_max_links integer default 8
)
returns table (
  pending_link_id uuid,
  pending_revision integer,
  pending_state text,
  order_id uuid,
  customer_id uuid,
  provider_attempt_id uuid,
  order_status text,
  execution_scope_sha256 text
)
language plpgsql
security definer
set search_path = pg_catalog, public
as $resolve_flight_consumer_duffel_pending_links_for_attempt$
#variable_conflict error
declare
  v_attempt public.flight_provider_request_attempts;
  v_pending record;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'Flight Duffel bounded pending webhook resolution is service-role only';
  end if;
  if p_attempt_id is null or p_expected_terminal_revision <> 2
    or p_max_links not between 1 and 8 then
    raise exception 'Flight Duffel bounded pending webhook resolution is invalid';
  end if;
  select attempt.* into v_attempt
    from public.flight_provider_request_attempts as attempt
   where attempt.id = p_attempt_id for share;
  if not found
    or v_attempt.revision <> p_expected_terminal_revision
    or v_attempt.state not in ('succeeded', 'failed', 'ambiguous')
    or v_attempt.consumer_flow_version <> 1
    or v_attempt.operation <> 'create_order'
    or v_attempt.execution_mode <> 'test'
    or v_attempt.provider_code <> 'duffel'
    or v_attempt.retry_authorized then
    raise exception 'Flight Duffel terminal attempt is unavailable';
  end if;
  perform public.assert_flight_consumer_preview_runtime_v1(
    v_attempt.execution_scope_sha256, 'provider_event'
  );
  for v_pending in
    select pending.id
      from public.flight_consumer_duffel_webhook_pending_links as pending
      left join public.flight_consumer_duffel_webhook_pending_link_resolutions
        as resolution on resolution.pending_link_id = pending.id
     where pending.provider_attempt_id = v_attempt.id
       and pending.execution_mode = 'test'
       and pending.execution_scope_sha256 = v_attempt.execution_scope_sha256
       and resolution.id is null
     order by pending.created_at, pending.id
     limit p_max_links
  loop
    return query select *
      from public.resolve_flight_consumer_duffel_pending_webhook_link_v1(
        v_pending.id, 0
      );
  end loop;
end;
$resolve_flight_consumer_duffel_pending_links_for_attempt$;

revoke all on table public.flight_consumer_duffel_webhook_pending_links
  from public, anon, authenticated, service_role;
revoke all on table public.flight_consumer_duffel_webhook_pending_link_resolutions
  from public, anon, authenticated, service_role;
revoke all on function
  public.reject_flight_consumer_duffel_pending_link_mutation_v1()
  from public, anon, authenticated, service_role;
revoke all on function
  public.enqueue_flight_consumer_duffel_pending_webhook_link_v1(
    uuid, integer, text, text
  ) from public, anon, authenticated, service_role;
revoke all on function
  public.resolve_flight_consumer_duffel_pending_webhook_link_v1(uuid, integer)
  from public, anon, authenticated, service_role;
revoke all on function
  public.resolve_flight_consumer_duffel_pending_links_for_attempt_v1(
    uuid, integer, integer
  ) from public, anon, authenticated, service_role;

grant execute on function
  public.enqueue_flight_consumer_duffel_pending_webhook_link_v1(
    uuid, integer, text, text
  ) to service_role;
grant execute on function
  public.resolve_flight_consumer_duffel_pending_webhook_link_v1(uuid, integer)
  to service_role;
grant execute on function
  public.resolve_flight_consumer_duffel_pending_links_for_attempt_v1(
    uuid, integer, integer
  ) to service_role;

comment on table public.flight_consumer_duffel_webhook_pending_links is
  'Append-only candidate association for a verified unlinked Duffel TEST order.created envelope and one immutable local create-order attempt.';
comment on table public.flight_consumer_duffel_webhook_pending_link_resolutions is
  'Append-only terminal linked/review resolution for a Duffel TEST pending webhook association; the original webhook ledger envelope is never rewritten.';
comment on function
  public.enqueue_flight_consumer_duffel_pending_webhook_link_v1(
    uuid, integer, text, text
  ) is 'Enqueues one digest-only TEST order.created association while its exact create-order attempt is dispatching or terminal; it never dispatches a provider request.';
comment on function
  public.resolve_flight_consumer_duffel_pending_webhook_link_v1(uuid, integer)
  is 'CAS-resolves one append-only pending Duffel TEST webhook association only after exact provider-attempt terminalization.';
comment on function
  public.resolve_flight_consumer_duffel_pending_links_for_attempt_v1(
    uuid, integer, integer
  ) is 'Boundedly resolves up to eight pending Duffel TEST webhook associations after exact local attempt terminalization; it performs no provider operation.';

do $flight_consumer_preview_090_postcondition$
declare
  v_safe_count integer;
  v_enqueue_source text;
  v_resolve_source text;
  v_bounded_source text;
begin
  select count(*)::integer into v_safe_count
    from public.flight_runtime_controls as control
   where control.control_key = 'global'
     and control.execution_kill_switch_engaged
     and not control.synthetic_execution_enabled
     and not control.provider_sandbox_traffic_enabled
     and not control.provider_live_traffic_enabled
     and not control.shopping_enabled
     and not control.order_enabled
     and not control.payment_enabled
     and not control.ticketing_enabled
     and not control.servicing_enabled
     and not control.provider_events_enabled
     and not control.production_release_enabled;
  select routine.prosrc into v_enqueue_source
    from pg_catalog.pg_proc as routine
   where routine.oid = to_regprocedure(
     'public.enqueue_flight_consumer_duffel_pending_webhook_link_v1(uuid,integer,text,text)'
   );
  select routine.prosrc into v_resolve_source
    from pg_catalog.pg_proc as routine
   where routine.oid = to_regprocedure(
     'public.resolve_flight_consumer_duffel_pending_webhook_link_v1(uuid,integer)'
   );
  select routine.prosrc into v_bounded_source
    from pg_catalog.pg_proc as routine
   where routine.oid = to_regprocedure(
     'public.resolve_flight_consumer_duffel_pending_links_for_attempt_v1(uuid,integer,integer)'
   );
  if v_safe_count <> 1
    or not exists (
      select 1 from pg_catalog.pg_class as relation
       where relation.oid = to_regclass(
         'public.flight_consumer_duffel_webhook_pending_links'
       ) and relation.relrowsecurity and relation.relforcerowsecurity
    )
    or not exists (
      select 1 from pg_catalog.pg_class as relation
       where relation.oid = to_regclass(
         'public.flight_consumer_duffel_webhook_pending_link_resolutions'
       ) and relation.relrowsecurity and relation.relforcerowsecurity
    )
    or v_enqueue_source is null
    or position('v_ledger.provider_live_mode is distinct from false'
      in v_enqueue_source) = 0
    or position('attempt.state = ''dispatching''' in v_enqueue_source) = 0
    or v_resolve_source is null
    or position('v_attempt.state = ''dispatching''' in v_resolve_source) = 0
    or position('v_outcome := ''linked''' in v_resolve_source) = 0
    or v_bounded_source is null
    or position('p_max_links not between 1 and 8' in v_bounded_source) = 0
    or position('limit p_max_links' in v_bounded_source) = 0
    or not has_function_privilege(
      'service_role',
      'public.enqueue_flight_consumer_duffel_pending_webhook_link_v1(uuid,integer,text,text)',
      'EXECUTE'
    )
    or not has_function_privilege(
      'service_role',
      'public.resolve_flight_consumer_duffel_pending_webhook_link_v1(uuid,integer)',
      'EXECUTE'
    )
    or not has_function_privilege(
      'service_role',
      'public.resolve_flight_consumer_duffel_pending_links_for_attempt_v1(uuid,integer,integer)',
      'EXECUTE'
    )
    or has_function_privilege(
      'anon',
      'public.resolve_flight_consumer_duffel_pending_webhook_link_v1(uuid,integer)',
      'EXECUTE'
    )
    or has_function_privilege(
      'authenticated',
      'public.resolve_flight_consumer_duffel_pending_webhook_link_v1(uuid,integer)',
      'EXECUTE'
    )
    or has_table_privilege(
      'service_role',
      'public.flight_consumer_duffel_webhook_pending_links',
      'SELECT,INSERT,UPDATE,DELETE'
    ) then
    raise exception 'Flight Consumer Preview migration 090 postcondition failed';
  end if;
end;
$flight_consumer_preview_090_postcondition$;

commit;

-- Mirrored from migrations/202608260130_flight_consumer_completion_lease.sql.
begin;

-- Order completion is a resumable, externally mutating workflow. This
-- digest-only lease serializes the HTTP completion coordinator without ever
-- authorizing a Stripe or Duffel dispatch. Durable payment/provider journals
-- remain the sole authority for those side effects.
do $flight_consumer_preview_091_dependencies$
begin
  if to_regclass('public.flight_runtime_controls') is null
    or to_regclass('public.flight_orders') is null
    or to_regclass('public.flight_passenger_refs') is null
    or to_regclass('public.flight_ticket_documents') is null
    or to_regclass('public.flight_payment_operation_attempts') is null
    or to_regclass('public.flight_provider_request_attempts') is null
    or to_regclass('public.flight_consumer_duffel_webhook_pending_links') is null
    or to_regprocedure(
      'public.resolve_flight_consumer_duffel_pending_links_for_attempt_v1(uuid,integer,integer)'
    ) is null then
    raise exception 'Flight Consumer Preview completion lease requires migrations 068 through 090';
  end if;
  if to_regprocedure('extensions.digest(bytea,text)') is null then
    raise exception 'Flight Consumer Preview completion lease requires reviewed SHA-256 support';
  end if;
end;
$flight_consumer_preview_091_dependencies$;

do $flight_consumer_preview_091_relocked_precondition$
declare
  v_safe_count integer;
begin
  select count(*)::integer into v_safe_count
    from public.flight_runtime_controls as control
   where control.control_key = 'global'
     and control.execution_kill_switch_engaged
     and not control.synthetic_execution_enabled
     and not control.provider_sandbox_traffic_enabled
     and not control.provider_live_traffic_enabled
     and not control.shopping_enabled
     and not control.order_enabled
     and not control.payment_enabled
     and not control.ticketing_enabled
     and not control.servicing_enabled
     and not control.provider_events_enabled
     and not control.production_release_enabled;
  if v_safe_count <> 1 then
    raise exception 'Flight Consumer Preview migration 091 requires relock before hardening';
  end if;
end;
$flight_consumer_preview_091_relocked_precondition$;

-- Idempotency keys are customer-scoped within one execution scope. order_id is
-- the primary key, so the same order can never be rebound to a different key
-- or request digest. Only hashes enter this table; payment references and the
-- raw HTTP Idempotency-Key remain outside PostgreSQL.
create table public.flight_consumer_completion_leases (
  order_id uuid primary key references public.flight_orders(id) on delete restrict,
  customer_id uuid not null references public.profiles(id) on delete restrict,
  execution_mode text not null default 'test' check (execution_mode = 'test'),
  execution_scope_sha256 text not null
    check (execution_scope_sha256 ~ '^[0-9a-f]{64}$'),
  idempotency_key_sha256 text not null
    check (idempotency_key_sha256 ~ '^[0-9a-f]{64}$'),
  request_sha256 text not null check (request_sha256 ~ '^[0-9a-f]{64}$'),
  lease_state text not null check (lease_state in ('processing', 'released', 'completed')),
  lease_revision integer not null default 0 check (lease_revision >= 0),
  lease_token_sha256 text check (
    lease_token_sha256 is null or lease_token_sha256 ~ '^[0-9a-f]{64}$'
  ),
  completed_owner_token_sha256 text check (
    completed_owner_token_sha256 is null
    or completed_owner_token_sha256 ~ '^[0-9a-f]{64}$'
  ),
  lease_acquired_at timestamptz,
  lease_expires_at timestamptz,
  heartbeat_at timestamptz,
  processing_attempt_count integer not null default 1
    check (processing_attempt_count >= 1),
  outcome_sha256 text check (
    outcome_sha256 is null or outcome_sha256 ~ '^[0-9a-f]{64}$'
  ),
  result_order_status text check (
    result_order_status is null or result_order_status = 'ticketed'
  ),
  result_issued_ticket_count integer check (
    result_issued_ticket_count is null or result_issued_ticket_count > 0
  ),
  last_failure_sha256 text check (
    last_failure_sha256 is null or last_failure_sha256 ~ '^[0-9a-f]{64}$'
  ),
  completed_at timestamptz,
  created_at timestamptz not null default clock_timestamp(),
  updated_at timestamptz not null default clock_timestamp(),
  unique (execution_scope_sha256, customer_id, idempotency_key_sha256),
  foreign key (order_id, customer_id)
    references public.flight_orders(id, customer_id) on delete restrict,
  check (
    (lease_state = 'processing'
      and lease_token_sha256 is not null
      and completed_owner_token_sha256 is null
      and lease_acquired_at is not null
      and lease_expires_at is not null
      and heartbeat_at is not null
      and outcome_sha256 is null
      and result_order_status is null
      and result_issued_ticket_count is null
      and completed_at is null)
    or (lease_state = 'released'
      and lease_token_sha256 is null
      and completed_owner_token_sha256 is null
      and lease_acquired_at is not null
      and lease_expires_at is null
      and heartbeat_at is not null
      and outcome_sha256 is null
      and result_order_status is null
      and result_issued_ticket_count is null
      and last_failure_sha256 is not null
      and completed_at is null)
    or (lease_state = 'completed'
      and lease_token_sha256 is null
      and lease_expires_at is null
      and outcome_sha256 is not null
      and result_order_status = 'ticketed'
      and result_issued_ticket_count > 0
      and completed_at is not null)
  ),
  check (
    lease_acquired_at is null
    or (heartbeat_at >= lease_acquired_at and updated_at >= lease_acquired_at)
  ),
  check (lease_expires_at is null or lease_expires_at > heartbeat_at),
  check (completed_at is null or completed_at >= created_at),
  check (updated_at >= created_at)
);

create index flight_consumer_completion_leases_state_expiry_idx
  on public.flight_consumer_completion_leases (lease_state, lease_expires_at)
  where lease_state = 'processing';

create function public.protect_flight_consumer_completion_lease_v1()
returns trigger
language plpgsql
security definer
set search_path = pg_catalog, public
as $protect_flight_consumer_completion_lease$
begin
  if tg_op = 'DELETE' then
    raise exception 'Flight completion lease evidence is append-preserving';
  end if;
  if tg_op = 'INSERT' then
    if new.lease_revision <> 0 or new.processing_attempt_count <> 1 then
      raise exception 'Flight completion lease must begin at its first exact revision';
    end if;
    return new;
  end if;
  if new.order_id is distinct from old.order_id
    or new.customer_id is distinct from old.customer_id
    or new.execution_mode is distinct from old.execution_mode
    or new.execution_scope_sha256 is distinct from old.execution_scope_sha256
    or new.idempotency_key_sha256 is distinct from old.idempotency_key_sha256
    or new.request_sha256 is distinct from old.request_sha256
    or new.created_at is distinct from old.created_at then
    raise exception 'Flight completion lease identity is immutable';
  end if;
  if old.lease_state = 'completed' then
    raise exception 'Completed Flight completion lease evidence is immutable';
  end if;
  if new.updated_at <= old.updated_at then
    raise exception 'Flight completion lease time must advance';
  end if;

  -- Heartbeats preserve the owner token and revision. They can only advance
  -- the two bounded liveness timestamps.
  if new.lease_revision = old.lease_revision then
    if old.lease_state <> 'processing'
      or new.lease_state <> 'processing'
      or new.lease_token_sha256 is distinct from old.lease_token_sha256
      or new.completed_owner_token_sha256
        is distinct from old.completed_owner_token_sha256
      or new.lease_acquired_at is distinct from old.lease_acquired_at
      or new.processing_attempt_count <> old.processing_attempt_count
      or new.outcome_sha256 is distinct from old.outcome_sha256
      or new.result_order_status is distinct from old.result_order_status
      or new.result_issued_ticket_count
        is distinct from old.result_issued_ticket_count
      or new.last_failure_sha256 is distinct from old.last_failure_sha256
      or new.completed_at is distinct from old.completed_at
      or new.heartbeat_at <= old.heartbeat_at
      or new.lease_expires_at <= old.lease_expires_at then
      raise exception 'Flight completion lease heartbeat is malformed';
    end if;
    return new;
  end if;

  if new.lease_revision <> old.lease_revision + 1 then
    raise exception 'Flight completion lease revision must advance by exact CAS';
  end if;
  if new.lease_state = 'processing' then
    if old.lease_state not in ('processing', 'released')
      or new.processing_attempt_count <> old.processing_attempt_count + 1
      or new.lease_token_sha256 is not distinct from old.lease_token_sha256 then
      raise exception 'Flight completion lease reclaim is malformed';
    end if;
    return new;
  end if;
  if new.lease_state = 'released' then
    if old.lease_state <> 'processing'
      or new.processing_attempt_count <> old.processing_attempt_count then
      raise exception 'Flight completion lease release is malformed';
    end if;
    return new;
  end if;
  if new.lease_state = 'completed' then
    if old.lease_state not in ('processing', 'released')
      or new.processing_attempt_count <> old.processing_attempt_count then
      raise exception 'Flight completion lease result is malformed';
    end if;
    return new;
  end if;
  raise exception 'Flight completion lease transition is not authorized';
end;
$protect_flight_consumer_completion_lease$;

create trigger flight_consumer_completion_lease_guard
before insert or update or delete on public.flight_consumer_completion_leases
for each row execute function public.protect_flight_consumer_completion_lease_v1();

create function public.acquire_flight_consumer_completion_lease_v1(
  p_customer_id uuid,
  p_order_id uuid,
  p_idempotency_key_sha256 text,
  p_request_sha256 text,
  p_execution_scope_sha256 text,
  p_lease_token_sha256 text,
  p_lease_duration_seconds integer
)
returns table (
  decision text,
  lease_revision integer,
  lease_state text,
  lease_token_sha256 text,
  lease_expires_at timestamptz,
  order_status text,
  issued_ticket_count integer,
  provider_attempt_state text,
  provider_attempt_revision integer,
  payment_attempt_state text,
  payment_attempt_revision integer,
  provider_redispatch_authorized boolean
)
language plpgsql
security definer
set search_path = pg_catalog, public, extensions
as $acquire_flight_consumer_completion_lease$
#variable_conflict error
declare
  v_order public.flight_orders;
  v_lease public.flight_consumer_completion_leases;
  v_provider public.flight_provider_request_attempts;
  v_capture public.flight_payment_operation_attempts;
  v_has_lease boolean;
  v_expected integer;
  v_issued integer;
  v_exact_ticketed boolean;
  v_now timestamptz := clock_timestamp();
  v_reclaim_at timestamptz;
  v_auto_outcome_sha256 text;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'Flight completion lease is service-role only';
  end if;
  if p_customer_id is null or p_order_id is null
    or p_idempotency_key_sha256 is null
    or p_idempotency_key_sha256 !~ '^[0-9a-f]{64}$'
    or p_request_sha256 is null or p_request_sha256 !~ '^[0-9a-f]{64}$'
    or p_execution_scope_sha256 is null
    or p_execution_scope_sha256 !~ '^[0-9a-f]{64}$'
    or p_lease_token_sha256 is null
    or p_lease_token_sha256 !~ '^[0-9a-f]{64}$'
    or p_lease_duration_seconds is null
    or p_lease_duration_seconds not between 30 and 300 then
    raise exception 'Flight completion lease input is invalid';
  end if;

  -- Every RPC in this contract uses the same order: order, lease, provider
  -- create-order journal, then Stripe capture journal.
  select * into v_order
    from public.flight_orders as flight_order
   where flight_order.id = p_order_id
   for update;
  if not found
    or v_order.customer_id is distinct from p_customer_id
    or v_order.execution_mode <> 'test'
    or v_order.provider_code <> 'duffel'
    or v_order.execution_scope_sha256 is distinct from p_execution_scope_sha256 then
    raise exception 'Flight completion order owner or execution scope does not match';
  end if;

  select * into v_lease
    from public.flight_consumer_completion_leases as completion_lease
   where completion_lease.order_id = p_order_id
   for update;
  v_has_lease := found;

  select * into v_provider
    from public.flight_provider_request_attempts as attempt
   where attempt.order_id = p_order_id
     and attempt.consumer_flow_version = 1
     and attempt.operation = 'create_order'
   for update;
  select * into v_capture
    from public.flight_payment_operation_attempts as attempt
   where attempt.order_id = p_order_id
     and attempt.operation = 'capture'
   for update;

  select count(*)::integer into v_expected
    from public.flight_passenger_refs as passenger
   where passenger.order_id = p_order_id;
  select count(*)::integer into v_issued
    from public.flight_ticket_documents as document
   where document.order_id = p_order_id
     and document.document_type = 'electronic_ticket'
     and document.status = 'issued';
  v_exact_ticketed := v_order.status = 'ticketed'
    and v_order.provider_order_ref_ciphertext is not null
    and v_order.provider_order_ref_sha256 is not null
    and v_expected > 0
    and v_issued = v_expected
    and not exists (
      select 1
        from public.flight_passenger_refs as passenger
       where passenger.order_id = p_order_id
         and (select count(*)
                from public.flight_ticket_documents as document
               where document.order_id = p_order_id
                 and document.passenger_ref_id = passenger.id
                 and document.document_type = 'electronic_ticket'
                 and document.status = 'issued') <> 1
    )
    and v_provider.id is not null
    and v_provider.state = 'succeeded'
    and v_provider.revision = 2
    and v_capture.id is not null
    and v_capture.state = 'succeeded'
    and v_capture.revision = 2;

  if v_has_lease then
    if v_lease.customer_id is distinct from p_customer_id
      or v_lease.execution_mode <> 'test'
      or v_lease.execution_scope_sha256 is distinct from p_execution_scope_sha256
      or v_lease.idempotency_key_sha256 is distinct from p_idempotency_key_sha256
      or v_lease.request_sha256 is distinct from p_request_sha256 then
      raise exception 'Flight completion idempotency key or request collides';
    end if;
    if v_lease.lease_state = 'completed' then
      if v_lease.result_order_status <> 'ticketed'
        or v_lease.result_issued_ticket_count is null
        or v_lease.result_issued_ticket_count < 1 then
        raise exception 'Flight completion replay result is malformed';
      end if;
      return query select
        'replayed'::text, v_lease.lease_revision, v_lease.lease_state,
        null::text, null::timestamptz, v_lease.result_order_status,
        v_lease.result_issued_ticket_count, v_provider.state,
        v_provider.revision, v_capture.state, v_capture.revision, false;
      return;
    end if;
  end if;

  if v_order.status = 'ticketed' and not v_exact_ticketed then
    raise exception 'Ticketed Flight completion lacks exact durable evidence';
  end if;
  if v_exact_ticketed then
    v_auto_outcome_sha256 := encode(
      extensions.digest(
        convert_to(
          jsonb_build_object(
            'domain', 'iratepilot.flight.consumer-completion-durable-replay.v1',
            'order_id', p_order_id::text,
            'customer_id', p_customer_id::text,
            'request_sha256', p_request_sha256,
            'issued_ticket_count', v_issued
          )::text,
          'UTF8'
        ),
        'sha256'
      ),
      'hex'
    );
    if v_has_lease then
      update public.flight_consumer_completion_leases
         set lease_state = 'completed',
             lease_revision = v_lease.lease_revision + 1,
             completed_owner_token_sha256 = v_lease.lease_token_sha256,
             lease_token_sha256 = null,
             lease_expires_at = null,
             outcome_sha256 = v_auto_outcome_sha256,
             result_order_status = 'ticketed',
             result_issued_ticket_count = v_issued,
             completed_at = v_now,
             updated_at = greatest(v_now, v_lease.updated_at + interval '1 microsecond')
       where order_id = p_order_id
         and lease_revision = v_lease.lease_revision
      returning * into v_lease;
    else
      insert into public.flight_consumer_completion_leases (
        order_id, customer_id, execution_mode, execution_scope_sha256,
        idempotency_key_sha256, request_sha256, lease_state, lease_revision,
        processing_attempt_count, outcome_sha256, result_order_status,
        result_issued_ticket_count, completed_at, created_at, updated_at
      ) values (
        p_order_id, p_customer_id, 'test', p_execution_scope_sha256,
        p_idempotency_key_sha256, p_request_sha256, 'completed', 0, 1,
        v_auto_outcome_sha256, 'ticketed', v_issued, v_now, v_now, v_now
      ) returning * into v_lease;
    end if;
    if not found then
      raise exception 'Flight completion durable replay CAS failed';
    end if;
    return query select
      'replayed'::text, v_lease.lease_revision, v_lease.lease_state,
      null::text, null::timestamptz, v_lease.result_order_status,
      v_lease.result_issued_ticket_count, v_provider.state,
      v_provider.revision, v_capture.state, v_capture.revision, false;
    return;
  end if;

  if not v_has_lease then
    insert into public.flight_consumer_completion_leases (
      order_id, customer_id, execution_mode, execution_scope_sha256,
      idempotency_key_sha256, request_sha256, lease_state, lease_revision,
      lease_token_sha256, lease_acquired_at, lease_expires_at, heartbeat_at,
      processing_attempt_count, created_at, updated_at
    ) values (
      p_order_id, p_customer_id, 'test', p_execution_scope_sha256,
      p_idempotency_key_sha256, p_request_sha256, 'processing', 0,
      p_lease_token_sha256, v_now,
      v_now + make_interval(secs => p_lease_duration_seconds), v_now, 1,
      v_now, v_now
    ) returning * into v_lease;
    return query select
      'acquired'::text, v_lease.lease_revision, v_lease.lease_state,
      v_lease.lease_token_sha256, v_lease.lease_expires_at, v_order.status,
      null::integer, v_provider.state, v_provider.revision, v_capture.state,
      v_capture.revision, false;
    return;
  end if;

  if v_lease.lease_state = 'processing'
    and v_lease.lease_expires_at > v_now then
    return query select
      'processing'::text, v_lease.lease_revision, v_lease.lease_state,
      null::text, v_lease.lease_expires_at, v_order.status, null::integer,
      v_provider.state, v_provider.revision, v_capture.state,
      v_capture.revision, false;
    return;
  end if;

  -- A lease timeout is never provider authority. Reclaim reads both durable
  -- journals under lock and leaves the lease untouched while either dispatch
  -- is still inside its exact SQL deadline. An expired dispatch is reclaimable
  -- only so the application can execute its journal-specific retrieve/review
  -- path; provider_redispatch_authorized remains false.
  if (v_provider.state = 'dispatching' and v_provider.dispatch_not_after > v_now)
    or (v_capture.state = 'dispatching' and v_capture.dispatch_not_after > v_now) then
    return query select
      'processing'::text, v_lease.lease_revision, v_lease.lease_state,
      null::text, v_lease.lease_expires_at, v_order.status, null::integer,
      v_provider.state, v_provider.revision, v_capture.state,
      v_capture.revision, false;
    return;
  end if;

  v_reclaim_at := greatest(v_now, v_lease.updated_at + interval '1 microsecond');
  update public.flight_consumer_completion_leases
     set lease_state = 'processing',
         lease_revision = v_lease.lease_revision + 1,
         lease_token_sha256 = p_lease_token_sha256,
         completed_owner_token_sha256 = null,
         lease_acquired_at = v_reclaim_at,
         lease_expires_at =
           v_reclaim_at + make_interval(secs => p_lease_duration_seconds),
         heartbeat_at = v_reclaim_at,
         processing_attempt_count = v_lease.processing_attempt_count + 1,
         updated_at = v_reclaim_at
   where order_id = p_order_id
     and lease_revision = v_lease.lease_revision
     and lease_state = v_lease.lease_state
  returning * into v_lease;
  if not found then
    raise exception 'Flight completion lease reclaim CAS failed';
  end if;
  return query select
    'reclaimed'::text, v_lease.lease_revision, v_lease.lease_state,
    v_lease.lease_token_sha256, v_lease.lease_expires_at, v_order.status,
    null::integer, v_provider.state, v_provider.revision, v_capture.state,
    v_capture.revision, false;
exception
  when unique_violation then
    raise exception 'Flight completion idempotency key collides within the customer scope';
end;
$acquire_flight_consumer_completion_lease$;

create function public.heartbeat_flight_consumer_completion_lease_v1(
  p_order_id uuid,
  p_expected_revision integer,
  p_lease_token_sha256 text,
  p_lease_duration_seconds integer
)
returns table (
  decision text,
  lease_revision integer,
  lease_state text,
  lease_expires_at timestamptz,
  order_status text,
  issued_ticket_count integer
)
language plpgsql
security definer
set search_path = pg_catalog, public
as $heartbeat_flight_consumer_completion_lease$
#variable_conflict error
declare
  v_order public.flight_orders;
  v_lease public.flight_consumer_completion_leases;
  v_now timestamptz := clock_timestamp();
  v_heartbeat_at timestamptz;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'Flight completion lease heartbeat is service-role only';
  end if;
  if p_order_id is null or p_expected_revision is null or p_expected_revision < 0
    or p_lease_token_sha256 is null
    or p_lease_token_sha256 !~ '^[0-9a-f]{64}$'
    or p_lease_duration_seconds is null
    or p_lease_duration_seconds not between 30 and 300 then
    raise exception 'Flight completion lease heartbeat input is invalid';
  end if;
  select * into v_order from public.flight_orders as flight_order
   where flight_order.id = p_order_id for update;
  select * into v_lease
    from public.flight_consumer_completion_leases as completion_lease
   where completion_lease.order_id = p_order_id for update;
  if v_order.id is null or v_lease.order_id is null
    or v_lease.lease_state <> 'processing'
    or v_lease.lease_revision <> p_expected_revision
    or v_lease.lease_token_sha256 is distinct from p_lease_token_sha256
    or v_lease.lease_expires_at <= v_now then
    raise exception 'Flight completion lease heartbeat lost ownership';
  end if;
  v_heartbeat_at := greatest(v_now, v_lease.heartbeat_at + interval '1 microsecond');
  update public.flight_consumer_completion_leases
     set heartbeat_at = v_heartbeat_at,
         lease_expires_at =
           v_heartbeat_at + make_interval(secs => p_lease_duration_seconds),
         updated_at = greatest(
           v_heartbeat_at, v_lease.updated_at + interval '1 microsecond'
         )
   where order_id = p_order_id
     and lease_revision = p_expected_revision
     and lease_state = 'processing'
     and lease_token_sha256 = p_lease_token_sha256
  returning * into v_lease;
  if not found then
    raise exception 'Flight completion lease heartbeat CAS failed';
  end if;
  return query select
    'heartbeat'::text, v_lease.lease_revision, v_lease.lease_state,
    v_lease.lease_expires_at, v_order.status, null::integer;
end;
$heartbeat_flight_consumer_completion_lease$;

create function public.complete_flight_consumer_completion_lease_v1(
  p_order_id uuid,
  p_expected_revision integer,
  p_lease_token_sha256 text,
  p_outcome_sha256 text,
  p_issued_ticket_count integer
)
returns table (
  decision text,
  lease_revision integer,
  lease_state text,
  lease_expires_at timestamptz,
  order_status text,
  issued_ticket_count integer
)
language plpgsql
security definer
set search_path = pg_catalog, public
as $complete_flight_consumer_completion_lease$
#variable_conflict error
declare
  v_order public.flight_orders;
  v_lease public.flight_consumer_completion_leases;
  v_provider public.flight_provider_request_attempts;
  v_capture public.flight_payment_operation_attempts;
  v_expected integer;
  v_issued integer;
  v_now timestamptz := clock_timestamp();
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'Flight completion lease result is service-role only';
  end if;
  if p_order_id is null or p_expected_revision is null or p_expected_revision < 0
    or p_lease_token_sha256 is null
    or p_lease_token_sha256 !~ '^[0-9a-f]{64}$'
    or p_outcome_sha256 is null or p_outcome_sha256 !~ '^[0-9a-f]{64}$'
    or p_issued_ticket_count is null or p_issued_ticket_count < 1 then
    raise exception 'Flight completion lease result input is invalid';
  end if;
  select * into v_order from public.flight_orders as flight_order
   where flight_order.id = p_order_id for update;
  select * into v_lease
    from public.flight_consumer_completion_leases as completion_lease
   where completion_lease.order_id = p_order_id for update;
  select * into v_provider
    from public.flight_provider_request_attempts as attempt
   where attempt.order_id = p_order_id
     and attempt.consumer_flow_version = 1
     and attempt.operation = 'create_order' for update;
  select * into v_capture
    from public.flight_payment_operation_attempts as attempt
   where attempt.order_id = p_order_id and attempt.operation = 'capture' for update;
  if v_order.id is null or v_lease.order_id is null then
    raise exception 'Flight completion lease result is unavailable';
  end if;
  if v_lease.lease_state = 'completed' then
    if v_lease.lease_revision <> p_expected_revision + 1
      or v_lease.completed_owner_token_sha256 is distinct from p_lease_token_sha256
      or v_lease.result_order_status <> 'ticketed'
      or v_lease.result_issued_ticket_count <> p_issued_ticket_count then
      raise exception 'Flight completion lease result replay collides';
    end if;
    return query select
      'replayed'::text, v_lease.lease_revision, v_lease.lease_state,
      null::timestamptz, v_lease.result_order_status,
      v_lease.result_issued_ticket_count;
    return;
  end if;
  if v_lease.lease_state <> 'processing'
    or v_lease.lease_revision <> p_expected_revision
    or v_lease.lease_token_sha256 is distinct from p_lease_token_sha256 then
    raise exception 'Flight completion lease result lost ownership';
  end if;
  select count(*)::integer into v_expected
    from public.flight_passenger_refs as passenger where passenger.order_id = p_order_id;
  select count(*)::integer into v_issued
    from public.flight_ticket_documents as document
   where document.order_id = p_order_id
     and document.document_type = 'electronic_ticket'
     and document.status = 'issued';
  if v_order.status <> 'ticketed'
    or v_order.provider_order_ref_ciphertext is null
    or v_order.provider_order_ref_sha256 is null
    or v_expected < 1
    or v_issued <> v_expected
    or v_issued <> p_issued_ticket_count
    or exists (
      select 1 from public.flight_passenger_refs as passenger
       where passenger.order_id = p_order_id
         and (select count(*) from public.flight_ticket_documents as document
               where document.order_id = p_order_id
                 and document.passenger_ref_id = passenger.id
                 and document.document_type = 'electronic_ticket'
                 and document.status = 'issued') <> 1
    )
    or v_provider.id is null or v_provider.state <> 'succeeded' or v_provider.revision <> 2
    or v_capture.id is null or v_capture.state <> 'succeeded' or v_capture.revision <> 2 then
    raise exception 'Flight completion result lacks exact durable ticket evidence';
  end if;
  update public.flight_consumer_completion_leases
     set lease_state = 'completed',
         lease_revision = v_lease.lease_revision + 1,
         completed_owner_token_sha256 = v_lease.lease_token_sha256,
         lease_token_sha256 = null,
         lease_expires_at = null,
         outcome_sha256 = p_outcome_sha256,
         result_order_status = 'ticketed',
         result_issued_ticket_count = p_issued_ticket_count,
         completed_at = v_now,
         updated_at = greatest(v_now, v_lease.updated_at + interval '1 microsecond')
   where order_id = p_order_id
     and lease_state = 'processing'
     and lease_revision = p_expected_revision
     and lease_token_sha256 = p_lease_token_sha256
  returning * into v_lease;
  if not found then
    raise exception 'Flight completion lease result CAS failed';
  end if;
  return query select
    'completed'::text, v_lease.lease_revision, v_lease.lease_state,
    null::timestamptz, v_lease.result_order_status,
    v_lease.result_issued_ticket_count;
end;
$complete_flight_consumer_completion_lease$;

create function public.release_flight_consumer_completion_lease_v1(
  p_order_id uuid,
  p_expected_revision integer,
  p_lease_token_sha256 text,
  p_failure_sha256 text
)
returns table (
  decision text,
  lease_revision integer,
  lease_state text,
  lease_expires_at timestamptz,
  order_status text,
  issued_ticket_count integer
)
language plpgsql
security definer
set search_path = pg_catalog, public, extensions
as $release_flight_consumer_completion_lease$
#variable_conflict error
declare
  v_order public.flight_orders;
  v_lease public.flight_consumer_completion_leases;
  v_provider public.flight_provider_request_attempts;
  v_capture public.flight_payment_operation_attempts;
  v_expected integer;
  v_issued integer;
  v_exact_ticketed boolean;
  v_now timestamptz := clock_timestamp();
  v_auto_outcome_sha256 text;
begin
  if coalesce(auth.role(), '') <> 'service_role' then
    raise exception 'Flight completion lease release is service-role only';
  end if;
  if p_order_id is null or p_expected_revision is null or p_expected_revision < 0
    or p_lease_token_sha256 is null
    or p_lease_token_sha256 !~ '^[0-9a-f]{64}$'
    or p_failure_sha256 is null or p_failure_sha256 !~ '^[0-9a-f]{64}$' then
    raise exception 'Flight completion lease release input is invalid';
  end if;
  select * into v_order from public.flight_orders as flight_order
   where flight_order.id = p_order_id for update;
  select * into v_lease
    from public.flight_consumer_completion_leases as completion_lease
   where completion_lease.order_id = p_order_id for update;
  select * into v_provider
    from public.flight_provider_request_attempts as attempt
   where attempt.order_id = p_order_id
     and attempt.consumer_flow_version = 1
     and attempt.operation = 'create_order' for update;
  select * into v_capture
    from public.flight_payment_operation_attempts as attempt
   where attempt.order_id = p_order_id and attempt.operation = 'capture' for update;
  if v_order.id is null or v_lease.order_id is null then
    raise exception 'Flight completion lease release is unavailable';
  end if;
  if v_lease.lease_state = 'completed' then
    return query select
      'replayed'::text, v_lease.lease_revision, v_lease.lease_state,
      null::timestamptz, v_lease.result_order_status,
      v_lease.result_issued_ticket_count;
    return;
  end if;

  select count(*)::integer into v_expected
    from public.flight_passenger_refs as passenger where passenger.order_id = p_order_id;
  select count(*)::integer into v_issued
    from public.flight_ticket_documents as document
   where document.order_id = p_order_id
     and document.document_type = 'electronic_ticket'
     and document.status = 'issued';
  v_exact_ticketed := v_order.status = 'ticketed'
    and v_order.provider_order_ref_ciphertext is not null
    and v_order.provider_order_ref_sha256 is not null
    and v_expected > 0 and v_issued = v_expected
    and not exists (
      select 1 from public.flight_passenger_refs as passenger
       where passenger.order_id = p_order_id
         and (select count(*) from public.flight_ticket_documents as document
               where document.order_id = p_order_id
                 and document.passenger_ref_id = passenger.id
                 and document.document_type = 'electronic_ticket'
                 and document.status = 'issued') <> 1
    )
    and v_provider.id is not null and v_provider.state = 'succeeded' and v_provider.revision = 2
    and v_capture.id is not null and v_capture.state = 'succeeded' and v_capture.revision = 2;
  if v_order.status = 'ticketed' and not v_exact_ticketed then
    raise exception 'Ticketed Flight completion release lacks exact durable evidence';
  end if;
  if v_exact_ticketed then
    v_auto_outcome_sha256 := encode(
      extensions.digest(
        convert_to(
          jsonb_build_object(
            'domain', 'iratepilot.flight.consumer-completion-release-replay.v1',
            'order_id', p_order_id::text,
            'request_sha256', v_lease.request_sha256,
            'issued_ticket_count', v_issued
          )::text,
          'UTF8'
        ),
        'sha256'
      ),
      'hex'
    );
    update public.flight_consumer_completion_leases
       set lease_state = 'completed',
           lease_revision = v_lease.lease_revision + 1,
           completed_owner_token_sha256 = v_lease.lease_token_sha256,
           lease_token_sha256 = null,
           lease_expires_at = null,
           outcome_sha256 = v_auto_outcome_sha256,
           result_order_status = 'ticketed',
           result_issued_ticket_count = v_issued,
           completed_at = v_now,
           updated_at = greatest(v_now, v_lease.updated_at + interval '1 microsecond')
     where order_id = p_order_id and lease_revision = v_lease.lease_revision
    returning * into v_lease;
    if not found then
      raise exception 'Flight completion release replay CAS failed';
    end if;
    return query select
      'replayed'::text, v_lease.lease_revision, v_lease.lease_state,
      null::timestamptz, v_lease.result_order_status,
      v_lease.result_issued_ticket_count;
    return;
  end if;

  if v_lease.lease_state <> 'processing'
    or v_lease.lease_revision <> p_expected_revision
    or v_lease.lease_token_sha256 is distinct from p_lease_token_sha256 then
    raise exception 'Flight completion lease release lost ownership';
  end if;
  if (v_provider.state = 'dispatching' and v_provider.dispatch_not_after > v_now)
    or (v_capture.state = 'dispatching' and v_capture.dispatch_not_after > v_now) then
    return query select
      'held'::text, v_lease.lease_revision, v_lease.lease_state,
      v_lease.lease_expires_at, v_order.status, null::integer;
    return;
  end if;
  update public.flight_consumer_completion_leases
     set lease_state = 'released',
         lease_revision = v_lease.lease_revision + 1,
         lease_token_sha256 = null,
         lease_expires_at = null,
         last_failure_sha256 = p_failure_sha256,
         updated_at = greatest(v_now, v_lease.updated_at + interval '1 microsecond')
   where order_id = p_order_id
     and lease_state = 'processing'
     and lease_revision = p_expected_revision
     and lease_token_sha256 = p_lease_token_sha256
  returning * into v_lease;
  if not found then
    raise exception 'Flight completion lease release CAS failed';
  end if;
  return query select
    'released'::text, v_lease.lease_revision, v_lease.lease_state,
    null::timestamptz, v_order.status, null::integer;
end;
$release_flight_consumer_completion_lease$;

